def weapons(me, enemy, arena):
    if me.righting:
        return []
    cmds = []
    sr = False
    if (me.inverted or me.on_side) and me.battery_health > 0:
        n = me.memory.get("sr", 0)
        if n < 2:
            me.memory["sr"] = n + 1
            cmds.append(self_right())
            sr = True
    else:
        me.memory["sr"] = 0
        f = me.weapons.get("back")
        if f and f.get("shots_left", 0) > 0 and f.get("ready", False):
            d = distance_to(enemy.x, enemy.y)
            b = bearing_to(enemy.x, enemy.y)
            es = hypot(enemy.vx, enemy.vy)
            if d < 0.9 and (b > 135 or b < -135) and es < 0.6:
                cmds.append(flip("back"))
    if not sr:
        s = me.weapons.get("front")
        if s and s.get("health", 0) > 0 and s.get("rpm", 0) < 4000:
            cmds.append(spin("front", 4200))
    return cmds

