def weapons(me, enemy, arena):
    cmds = []

    # Keep the left spinner at max RPM.
    spinner = me.weapons.get("left")
    if spinner and spinner.get("type") == "spinner":
        max_rpm = spinner.get("max_rpm", 0)
        if max_rpm:
            cmds.append(spin("left", max_rpm))

    # Try to grab with the front clamp when close.
    try:
        dist = distance_to(enemy.x, enemy.y)
    except Exception:
        dist = 0.0

    clamp = me.weapons.get("front")
    if clamp and clamp.get("type") == "clamp":
        state = clamp.get("state", "open")
        if dist < 0.5 and state not in ("holding", "closed"):
            cmds.append(grab("front"))
        elif state == "holding" and me.memory.get("hold_time", 0) > 2.0:
            cmds.append(release("front"))
            me.memory["hold_time"] = 0.0

    # Use the back flipper to throw when the enemy is roughly ahead.
    flipper = me.weapons.get("back")
    if flipper and flipper.get("type") == "flipper":
        bearing = bearing_to(enemy.x, enemy.y)
        if abs(bearing) < 15 and dist < 0.7 and flipper.get("shots_left", 0) > 0:
            cmds.append(flip("back"))

    # Update hold timer.
    if me.held:
        elapsed = arena.time_left - arena.time
        me.memory["hold_time"] = me.memory.get("hold_time", 0.0) + elapsed
    else:
        me.memory["hold_time"] = 0.0

    return cmds if cmds else None

